CREATE ROLE erp_app LOGIN PASSWORD '...' NOSUPERUSER NOBYPASSRLS;
CREATE ROLE erp_worker LOGIN PASSWORD '...' NOSUPERUSER BYPASSRLS;
CREATE ROLE erp_migrations LOGIN PASSWORD '...' NOSUPERUSER;
GRANT USAGE ON SCHEMA public TO erp_app, erp_worker, erp_migrations;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO erp_app, erp_worker;
GRANT ALL ON SCHEMA public TO erp_migrations;
REVOKE ALL ON SCHEMA public FROM PUBLIC;

roles_base_datos.unidad_trabajo:
class TenantUnitOfWork:
    def __init__(self, tenant_id: UUID):
        self.tenant_id = tenant_id
    async def __aenter__(self) -> AsyncSession:
        self.session = AsyncSessionLocal()
        self.tx = self.session.begin()
        await self.session.execute(text("SELECT set_current_tenant(:t)"), {"t": str(self.tenant_id)})
        return self.session
    async def __aexit__(self, exc_type, exc_val, exc_tb):
        try:
            if exc_type: await self.tx.rollback()
            else: await self.tx.commit()
        finally:
            await self.session.close()

