ALTER TABLE tventas ENABLE ROW LEVEL SECURITY;
ALTER TABLE tventas FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation_tventas ON tventas FOR ALL
USING (papeleria_id = NULLIF(current_setting('app.current_tenant_id', true),'')::uuid)
WITH CHECK (papeleria_id = NULLIF(current_setting('app.current_tenant_id', true),'')::uuid);
CREATE OR REPLACE FUNCTION set_current_tenant(p UUID) RETURNS void AS $$
BEGIN PERFORM set_config('app.current_tenant_id', p::text, true); END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
CREATE OR REPLACE FUNCTION generate_uuid_v7() RETURNS uuid AS $$
DECLARE v_time timestamptz := clock_timestamp(); v_secs bigint; v_msec bigint; v_buf bytea;
BEGIN
v_secs := EXTRACT(EPOCH FROM v_time)::bigint;
v_msec := (v_secs * 1000) + (EXTRACT(MILLISECONDS FROM v_time)::bigint % 1000);
v_buf := decode(lpad(to_hex(v_msec), 12, '0') || encode(gen_random_bytes(10), 'hex'), 'hex');
v_buf := set_byte(v_buf, 6, (get_byte(v_buf, 6) &amp; 15) | 112);
v_buf := set_byte(v_buf, 8, (get_byte(v_buf, 8) &amp; 63) | 128);
RETURN encode(v_buf, 'hex')::uuid;
END;
$$ LANGUAGE plpgsql VOLATILE;

archivo.codigo:
import Dexie, { Table } from 'dexie';
import Decimal from 'decimal.js';
export interface ArticuloLocal {
  id: string; sku: string; descripcion: string; precio_base: string;
  stock_actual: string; stock_reservado: string; unidad_medida: string;
  permite_decimales: boolean; activo: boolean; updated_at: string;
}
export interface VentaLocal {
  client_uuid: string; folio: string; operario_id: string; caja_id: string;
  sucursal_id: string; estacion_id: string; corte_id?: string;
  cliente_rel_id?: string; moneda: string; subtotal: string; impuestos: string;
  descuento_total: string; total: string;
  metodo_pago: 'efectivo'|'tarjeta'|'transferencia'|'mixto'|'puntos'|'credito';
  pagos: Array<{tipo: string; monto: string; referencia?: string}>;
  origen: 'pos'|'rompefila'; tipo_entrega: 'tienda'|'envio_express'|'pickup';
  detalles: any[];
  estado: 'pendiente_sync'|'sincronizada'|'conflicto'|'conflicto_corte_cerrado'|'cancelada';
  conflicto_motivo?: string; created_at: string; synced_at?: string; trace_id: string;
}
export class PosDB extends Dexie {
  articulos!: Table<ArticuloLocal, string>;
  ventas!: Table<VentaLocal, string>;
  folios!: Table<any, string>;
  meta!: Table<{clave: string; valor: string}, string>;
  constructor() {
    super('PosDB');
    this.version(1).stores({
      articulos: 'id, sku, descripcion, activo',
      ventas: 'client_uuid, estado, created_at',
      folios: 'estacion_id',
      meta: 'clave',
    });
  }
  async decrementarStockLocal(articulo_id: string, cantidad: Decimal): Promise<void> {
    await this.transaction('rw', this.articulos, async () => {
      const art = await this.articulos.get(articulo_id);
      if (!art) throw new Error(`Artículo ${articulo_id} no existe localmente`);
      await this.articulos.update(articulo_id, {
        stock_actual: new Decimal(art.stock_actual).minus(cantidad).toString()
      });
    });
  }
}
export const db = new PosDB();

// pos/src/api/outboxSync.ts — F21: logger estructurado · F38: helpers canonizados
import axios from 'axios';
import { db, VentaLocal } from '../db/dexieDb';
import { uuidv7 } from 'uuidv7';
import { logger } from '../lib/logger';  // F21: reemplaza console.log

const API_URL = import.meta.env.VITE_API_URL || 'https://api.papelmaind.com/api/v1';
export const api = axios.create({
  baseURL: API_URL, timeout: 15000,
  headers: { 'Content-Type': 'application/json' },
});
api.interceptors.request.use((config) => {
  const token = localStorage.getItem('pos_token');
  if (token) config.headers.Authorization = `Bearer ${token}`;
  config.headers['X-Trace-ID'] = uuidv7();
  return config;
});

// F38: helper canonizado — obtiene contexto del JWT decodificado
export function getContextFromJWT() {
  const token = localStorage.getItem('pos_token');
  if (!token) throw new Error('No JWT');
  const claims = JSON.parse(atob(token.split('.')[1]));
  return {
    operario_id: claims.operario_id,
    tenant_id: claims.tenant_id,
    caja_id: claims.caja_id,
    sucursal_id: claims.sucursal_id,
    estacion_id: claims.estacion_id,
  };
}

// F38: helper canonizado — obtiene siguiente folio del bloque asignado
export async function getNextFolio(): Promise<string> {
  const ctx = getContextFromJWT();
  const bloque = await db.folios.get(ctx.estacion_id);
  if (!bloque || bloque.folio_actual >= bloque.folio_hasta) {
    const { data } = await api.post('/pos/folios/refresh', { estacion_id: ctx.estacion_id });
    await db.folios.put({
      estacion_id: ctx.estacion_id,
      folio_actual: data.folio_desde,
      folio_hasta: data.folio_hasta,
      actualizado_en: new Date().toISOString(),
    });
  }
  const folio = `POS-${String(bloque!.folio_actual).padStart(6, '0')}`;
  await db.folios.update(ctx.estacion_id, { folio_actual: bloque!.folio_actual + 1 });
  return folio;
}

export async function syncPendingSales() {
  const pending = await db.ventas
    .where('estado').anyOf('pendiente_sync', 'conflicto', 'conflicto_corte_cerrado')
    .sortBy('created_at');
  if (pending.length === 0) return;
  const batch = pending.slice(0, 50);
  try {
    const { data } = await api.post('/pos/ventas/sync', { ventas: batch });
    for (const res of data.resultados) {
      const nuevoEstado = res.status === 'created' || res.status === 'duplicated'
        ? 'sincronizada'
        : (res.status === 'corte_cerrado' ? 'conflicto_corte_cerrado' : 'conflicto');
      await db.ventas.update(res.client_uuid, {
        estado: nuevoEstado,
        conflicto_motivo: res.motivo,
        synced_at: new Date().toISOString(),
      });
    }
    if (pending.length > 50) setTimeout(syncPendingSales, 1000);
  } catch (e: any) {
    logger.error('pos.sync_error', { msg: e.message });  // F21
  }
}

export function initSyncTriggers() {
  window.addEventListener('online', () => {
    logger.debug('pos.online_sync_start');  // F21
    syncPendingSales();
  });
  setInterval(async () => {
    if (navigator.onLine) {
      const count = await db.ventas
        .where('estado').anyOf('pendiente_sync', 'conflicto', 'conflicto_corte_cerrado')
        .count();
      if (count > 0) await syncPendingSales();
    }
  }, 30000);
}

// PaymentModal.tsx — F21: alert() → toast (RG-02/CHK-25)
import { useState, useMemo, useCallback } from 'react';
import Decimal from 'decimal.js';
import { db, VentaLocal } from '../db/dexieDb';
import { getContextFromJWT, getNextFolio } from '../api/outboxSync';
import { uuidv7 } from 'uuidv7';
import { useToast } from '../components/Toast';  // F21

export function PaymentModal({ items, total, onClose, onSuccess }: {
  items: any[]; total: string; onClose: () => void; onSuccess: (v: VentaLocal) => void;
}) {
  const { showToast } = useToast();  // F21
  const totalDec = useMemo(() => new Decimal(total), [total]);
  const [pagos, setPagos] = useState<{tipo: string; monto: string}[]>([
    { tipo: 'efectivo', monto: total }
  ]);
  const [procesando, setProcesando] = useState(false);
  const totalPagado = useMemo(
    () => pagos.reduce((sum, p) => sum.add(new Decimal(p.monto)), new Decimal(0)),
    [pagos]
  );
  const faltante = useMemo(() => totalDec.minus(totalPagado), [totalDec, totalPagado]);

  const handleCobrar = useCallback(async () => {
    if (faltante.gt(0)) { showToast('Falta cubrir el total', 'error'); return; }  // F21
    setProcesando(true);
    try {
      const ctx = getContextFromJWT();
      const folio = await getNextFolio();
      const client_uuid = uuidv7();
      const subtotal = items.reduce((s, i) => s.add(new Decimal(i.subtotal)), new Decimal(0));
      const impuestos = items.reduce(
        (s, i) => s.add(new Decimal(i.subtotal).mul(new Decimal(i.impuesto_tasa ?? '0.16'))),
        new Decimal(0)
      );
      const venta: VentaLocal = {
        client_uuid, folio, operario_id: ctx.operario_id, caja_id: ctx.caja_id,
        sucursal_id: ctx.sucursal_id, estacion_id: ctx.estacion_id,
        moneda: 'MXN', subtotal: subtotal.toFixed(2), impuestos: impuestos.toFixed(2),
        descuento_total: '0.00', total: totalDec.toFixed(2),
        metodo_pago: pagos.length === 1 ? (pagos[0].tipo as any) : 'mixto',
        pagos: pagos.map(p => ({ tipo: p.tipo, monto: p.monto })),
        detalles: items.map(i => ({
          articulo_id: i.articulo_id, cantidad: i.cantidad,
          precio_unitario: i.precio_unitario, subtotal: i.subtotal,
          impuesto_id: i.impuesto_id
        })),
        estado: 'pendiente_sync', created_at: new Date().toISOString(), trace_id: uuidv7(),
      };
      await db.transaction('rw', db.ventas, db.articulos, async () => {
        await db.ventas.add(venta);
        for (const item of items) {
          const art = await db.articulos.get(item.articulo_id);
          if (art) await db.articulos.update(item.articulo_id, {
            stock_actual: new Decimal(art.stock_actual).minus(item.cantidad).toString()
          });
        }
      });
      onSuccess(venta);
    } catch (e: any) {
      showToast(`Error: ${e.message}`, 'error');  // F21
    } finally { setProcesando(false); }
  }, [faltante, items, pagos, totalDec, onSuccess, showToast]);

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50">
      <div className="bg-white rounded-lg shadow-2xl w-full max-w-2xl">
        <div className="px-5 py-3 border-b-2 flex items-center justify-between"
          style={{ background: 'linear-gradient(90deg, #80FFFF 0%, #B3FBFB 100%)' }}>
          <h2 className="text-lg font-bold">Cobrar venta</h2>
          <button onClick={onClose}><i className="fas fa-times" /></button>
        </div>
        <div className="p-5">
          <div className="flex items-center justify-between mb-4">
            <span className="text-lg font-bold">TOTAL A PAGAR</span>
            <span className="text-3xl font-extrabold" style={{ color: '#0F8A5F' }}>
              ${totalDec.toFixed(2)}
            </span>
          </div>
          {faltante.gt(0) &amp;&amp; (
            <div className="flex justify-between text-red-500 font-bold mb-2">
              <span>FALTANTE</span><span>${faltante.toFixed(2)}</span>
            </div>
          )}
          <button onClick={handleCobrar} disabled={faltante.gt(0) || procesando}
            className="w-full py-4 rounded-lg font-extrabold text-lg disabled:opacity-50"
            style={{ background: 'linear-gradient(90deg, #7BFFB9 0%, #A5FFD6 100%)',
                     border: '2px solid #5EE0A8' }}>
            {procesando ? 'Procesando...' : `COBRAR $${totalDec.toFixed(2)}`}
          </button>
        </div>
      </div>
    </div>
  );
}

