# src/api/v1/whatsapp.py from uuid import UUID from fastapi import APIRouter, Depends, HTTPException from sqlalchemy import text from src.infrastructure.db.session import WorkerSessionLocal
async def resolve_tenant_context(db, phone_number_id: str) -> UUID: """F19: resuelve tenant por número RECEPTOR. F37: UNIQUE parcial en whatsapp_phone_number_id por tenant.""" row = (await db.execute(text(""" SELECT papeleria_id FROM papeleria_configuracion WHERE clave = 'whatsapp_phone_number_id' AND valor = :pnid LIMIT 1 """), {"pnid": phone_number_id})).first() if not row: raise HTTPException(404, "Número receptor no mapeado a ningún tenant") await db.execute(text("SELECT set_current_tenant(:t)"), {"t": str(row[0])}) return row[0]
async def resolve_whatsapp_token(db, tenant_id: UUID) -> str: """F36: resuelve el access_token de WhatsApp desde papeleria_api_keys.""" row = (await db.execute(text(""" SELECT api_key_encrypted FROM papeleria_api_keys WHERE papeleria_id = :tid AND servicio = 'whatsapp' AND entorno = 'produccion' LIMIT 1 """), {"tid": str(tenant_id)})).first() if not row: raise HTTPException(404, "Token WhatsApp no configurado para este tenant") from src.core.security import decrypt return decrypt(row[0])
@router.post("/whatsapp/webhook") async def whatsapp_webhook(request: Request): await validar_hmac_meta(request) body = await request.json() phone_number_id = extract_phone_number_id(body) async with WorkerSessionLocal() as db: tenant_id = await resolve_tenant_context(db, phone_number_id) wa_token = await resolve_whatsapp_token(db, tenant_id) # F36 await handle_inbound_message(db, tenant_id, wa_token, body) await db.commit() return {"status": "ok"}

