worker.codigo:
# src/infrastructure/workers/notification_worker.py — F36 token por tenant
import asyncio, json, httpx
from aiokafka import AIOKafkaConsumer
from sqlalchemy import text
from src.core.config import settings
from src.infrastructure.db.session import WorkerSessionLocal
from src.core.security import decrypt

async def _enviar_whatsapp(tenant_id, numero: str, payload: dict) -> dict:
    """F36: resuelve token por tenant desde papeleria_api_keys."""
    async with WorkerSessionLocal() as db:
        row = (await db.execute(text("""
            SELECT api_key_encrypted, webhook_url
            FROM papeleria_api_keys
            WHERE papeleria_id = :tid AND servicio = 'whatsapp'
              AND entorno = 'produccion' AND activo = true
            LIMIT 1
        """), {"tid": str(tenant_id)})).first()
        if not row:
            return {"ok": False, "error": "Token no configurado"}
        token = decrypt(row[0])
        phone_id = row[1] or settings.WHATSAPP_PHONE_NUMBER_ID

    url = f"https://graph.facebook.com/v18.0/{phone_id}/messages"
    headers = {"Authorization": f"Bearer {token}"}
    body = {
        "messaging_product": "whatsapp",
        "to": numero.replace("+", "").replace(" ", "").replace("-", ""),
    }
    if payload.get("tipoContenido") == "template":
        body["type"] = "template"
        body["template"] = {
            "name": payload["plantilla"]["nombre"],
            "language": {"code": payload["plantilla"].get("idioma", "es_MX")},
        }
    elif payload.get("tipoContenido") == "interactive":
        body["type"] = "interactive"
        body["interactive"] = payload["interactivo"]
    else:
        body["type"] = "text"
        body["text"] = {"body": payload.get("texto", "")[:4096]}

    delays = [1, 5, 15]
    async with httpx.AsyncClient(timeout=15.0) as client:
        for i in range(3):
            try:
                r = await client.post(url, json=body, headers=headers)
                if r.status_code == 200:
                    return {"ok": True, "mensajeExternoId": r.json().get("messages", [{}])[0].get("id")}
            except Exception as e:
                if i < 2: await asyncio.sleep(delays[i])
    return {"ok": False}

