@startuml despliegue
node "Cloud (VPS P0 / EKS P2+)" {
  node "API Pod (3-10 HPA)" {
    component FastAPI
    component Uvicorn4
  }
  node "Workers (StatefulSet)" {
    component "outbox_worker"
    component "loyalty_worker"
    component "cfdi_worker"
    component "notification_worker"
    component "ia_loop_worker"
    component "inventory_alert"
    component "reservation_sweeper"
    component "ai_campaign"
    component "dlq_consumer"
  }
  database "PostgreSQL 16 (RLS)"
  database Redis7
  queue Kafka
}
node "Edge (Cliente)" {
  node "POS PWA" { component IndexedDB; component ServiceWorker }
  node "Kiosco HTML"
  node "Web Next.js"
}
POS --> API : HTTPS + JWT
Kiosco --> API
Web --> API
API --> PostgreSQL : SET LOCAL
Workers --> PostgreSQL : BYPASSRLS
Workers --> Kafka
@enduml
